async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, g.P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!(await VISIBLE$(g.P_IT_OBJECT))) {
            await REFERRING();
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        } else if (obj == HIM) {
          if (!(await VISIBLE$(g.P_HIM_OBJECT))) {
            await REFERRING(true);
            return false;
          } else {
            obj = g.P_HIM_OBJECT;
          }
        }
        if ((await ULTIMATELY_IN$(obj)) || (obj == INTNUM || obj == HANDS)) {
        } else if ((obj == LEASH) && g.HANGING_IN_AIR) {
        } else {
          g.PRSO = obj;
          if (hasFlag(obj, TRYTAKEBIT) || (await UNTOUCHABLE$(obj)) || g.STUNNED) {
            taken = true;
          } else if (!(g.WINNER == PROTAGONIST)) {
            taken = false;
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
            taken = false;
          } else {
            taken = true;
          }
          if (taken && btst(ibits, SHAVE)) {
            if (1 < get(tbl, g.P_MATCHLEN)) {
              tell(S(g.YNH), " all those things!\n");
              return false;
            } else if (obj == NOT_HERE_OBJECT) {
              tell(S(g.YOU_CANT), "see that here!\n");
              return false;
            }
            if (g.WINNER == PROTAGONIST) {
              tell(S(g.YNH));
            } else {
              tell("It doesn't look like");
              await TPRINT(g.WINNER);
              tell(" has");
            }
            await THIS_IS_IT(obj);
            await TRPRINT(obj);
            return false;
          } else if (!taken && !(loc(PROTAGONIST) == obj) && (g.WINNER == PROTAGONIST)) {
            tell("[taking");
            await TPRINT(obj);
            tell(" first]\n");
          }
        }
      }
    }
  } else {
    return true;
  }
}

