async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm, rmbit = true) {
  let ohere = 0, lit = false;
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (rmbit && hasFlag(rm, ONBIT)) {
    lit = true;
  } else {
    put(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == PROTAGONIST) && (loc(PROTAGONIST) == rm)) {
        await DO_SL(PROTAGONIST, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = true;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

