async function V_FOOTNOTE() {
  g.C_ELAPSED = 0;
  if (!g.PRSO || !(g.PRSO == INTNUM)) {
    tell("Specify a number, as in \"FOOTNOTE 6.\"\n");
    return true;
  } else if (g.P_NUMBER == 1) {
    tell("These must be those special zero-gee dice which project their own gravitational field onto the nearest surface. Zero-gee dice are, of course, notoriously easy to load");
  } else if (g.P_NUMBER == 2) {
    tell(S(g.UNFAMILIAR), "Blather was your officious, tyrannical superior aboard the S.P.S. Feinstein. He was demoted because of his craven behavior during the destruction of the Feinstein");
  } else if (g.P_NUMBER == 3) {
    tell("The story of your acquaintance with Floyd and the episode on Resida are recounted in PLANETFALL");
  } else if (g.P_NUMBER == 4) {
    tell("This is, of course, impossible. To do this, the creature would have to be an order of magnitude larger. There are two possible explanations: 1. The creature actually extends part of its volume into a parallel dimension", S(g.CALLOUS_DISREGARD));
  } else if (g.P_NUMBER == 5 || g.P_NUMBER == 9 || g.P_NUMBER == 13) {
    tell("Kids: ");
    if (g.P_NUMBER == 5) {
      tell("drills");
    } else if (g.P_NUMBER == 9) {
      tell("zapguns");
    } else {
      tell("FREZONE (tm) explosives");
    }
    tell(" are very dangerous. Don't try this at home without adult supervision");
  } else if (g.P_NUMBER == 6) {
    tell("That was just an example");
  } else if (g.P_NUMBER == 7) {
    tell(S(g.UNFAMILIAR), "your frenzied (former) boss, Ensign Blather, would toss you into the Feinstein's brig for the tiniest violation of the Stellar Patrol's near-infinity of trivial regulations");
  } else if (g.P_NUMBER == 8) {
    tell("The author wishes to refute any claims that the use of footnotes is a ripoff from the interactive fiction version of THE HITCHHIKER'S GUIDE TO THE GALAXY. This is not true. Well, maybe it's a little bit true, in which case the author wishes to point out his right to rip off his own ideas. So there");
  } else if (g.P_NUMBER == 10) {
    g.AWAITING_REPLY = 1;
    await QUEUE(I_REPLY.id, 1);
    tell("Isn't it fun reading through all the footnotes?\n");
    return true;
  } else if (g.P_NUMBER == 11 || g.P_NUMBER == 12) {
    tell("How to keep a STATIONFALL player busy all day (Footnote 1");
    if (g.P_NUMBER == 11) {
      tell("2)");
    } else {
      tell("1)");
    }
  } else if (g.P_NUMBER == 14) {
    tell("Actually, it is only a myth that ostriches stick their heads in holes when frightened. The fact that this ostrich does can be attributed to: 1. an addling of the animal's brain caused by extended exposure to weightlessness", S(g.CALLOUS_DISREGARD));
  } else if (g.P_NUMBER == 15) {
    tell("IF you also played Planetfall, and IF you scrambled any magnetic cards in Planetfall by being careless with the magnet: GOTCHA AGAIN! (Footnote 16)\n");
    return true;
  } else if (g.P_NUMBER == 16) {
    tell("Reminds me of that old saying, \"Fool me once, shame on you. Fool me twice, shame on me!\"\n");
    return true;
  } else {
    tell("There is no Footnote ", N(g.P_NUMBER), S(g.PERIOD_CR));
    return true;
  }
  if (!g.READ_A_FOOTNOTE) {
    g.READ_A_FOOTNOTE = true;
    tell(". (Footnote 8)");
  }
  tell(S(g.PERIOD_CR));
  return true;
}

