async function PRE_TAKE() {
  if (g.STUNNED) {
    return (await YOURE_STUNNED("move that much"));
  } else if (await UNTOUCHABLE$(g.PRSO)) {
    return await CANT_REACH(g.PRSO);
  } else if (!(g.PRSI == HANDS || g.PRSI == TONGUE) && (await PRE_LOOK())) {
    return true;
  } else if (await LOC_CLOSED()) {
    return true;
  } else if (loc(PROTAGONIST) == g.PRSO) {
    tell("You're ");
    if (hasFlag(g.PRSO, INBIT)) {
      tell("i");
    } else {
      tell("o");
    }
    tell("n it, asteroid-brain!\n");
    return true;
  } else if ((loc(g.PRSO) == PROTAGONIST) || ((await ULTIMATELY_IN$(g.PRSO)) && !(hasFlag(g.PRSO, TAKEBIT)))) {
    if (hasFlag(g.PRSO, WORNBIT)) {
      tell("You're already wearing");
    } else {
      tell("You already have");
    }
    await TPRINT_PRSO();
    tell(S(g.PERIOD_CR));
    return true;
  } else if (loc(g.PRSO) == HEATING_CHAMBER) {
    await PERFORM(V.REACH_IN, HEATING_CHAMBER);
    return true;
  } else if ((g.PRSO == LEASH) && (g.PRSI == BALLOON)) {
    await PERFORM(V.REMOVE, LEASH);
    return true;
  } else if (!g.PRSI) {
    return false;
  } else if (loc(g.PRSO) == g.PRSI) {
    return false;
  } else if (g.PRSO == ME) {
    await PERFORM(V.DROP, g.PRSI);
    return true;
  } else if (g.PRSI == GLOBAL_ROOM) {
    if (await ULTIMATELY_IN$(g.PRSO)) {
      return await DO_WALK(P.OUT);
    } else {
      return false;
    }
  } else if ((g.PRSI == GARBAGE || g.PRSI == SCULPTURE) && (loc(g.PRSO) == g.HERE)) {
    return false;
  } else if (!(loc(g.PRSO) == g.PRSI)) {
    return await NOT_IN();
  } else {
    g.PRSI = false;
    return false;
  }
}

