async function GOTO(new_loc) {
  let old_here = 0;
  await apply(getProp(g.HERE, P.ACTION), M_EXIT);
  if ((loc(FLOYD) == g.HERE) && hasFlag(FLOYD, ACTIVEBIT)) {
    g.FLOYD_FOLLOW = true;
  }
  old_here = g.HERE;
  move(PROTAGONIST, new_loc);
  g.HERE = new_loc;
  g.LIT = await LIT$(g.HERE);
  g.BALLOON_ODOR = false;
  await apply(getProp(g.HERE, P.ACTION), M_ENTER);
  if ((await DESCRIBE_ROOM()) && !(g.VERBOSITY == 0)) {
    await DESCRIBE_OBJECTS();
  }
  if ((loc(OSTRICH) == old_here) && (await ULTIMATELY_IN$(OSTRICH_NIP)) && (await VISIBLE$(OSTRICH_NIP)) && !(g.HERE == TOP_OF_AIR_SHAFT)) {
    tell("   The ostrich, sniffing excitedly, ");
    if (await GLOBAL_IN$(BED, g.HERE)) {
      tell("follows you to the door, but hesitates as it notices the bed. The ostrich, who refuses to enter any room with a bed due to a bad experience in its youth, withdraws.\n");
      return true;
    } else if (hasFlag(loc(OSTRICH), WEIGHTLESSBIT)) {
      tell("follows you in an awkward fashion somewhere between swimming and flying.");
    } else {
      tell("trots eagerly after you.");
    }
    if (((g.HERE == SOUTH_CONNECTION) && (loc(OSTRICH) == GRIMY_PASSAGE)) || ((g.HERE == EAST_CONNECTION) && (loc(OSTRICH) == MAKESHIFT_CONNECTOR)) || (loc(OSTRICH) == ELEVATOR)) {
      if (g.LIT) {
        tell(" As the ostrich crosses into gravity, it emits a surprised squawk and does a graceless bellyflop. As it struggles to its feet, it appears that only its dignity was injured.");
      }
    } else if (((g.HERE == GRIMY_PASSAGE) && (loc(OSTRICH) == SOUTH_CONNECTION)) || ((g.HERE == MAKESHIFT_CONNECTOR) && (loc(OSTRICH) == EAST_CONNECTION)) || ((g.HERE == ELEVATOR) && hasFlag(ELEVATOR, WEIGHTLESSBIT))) {
      if (g.LIT) {
        tell(" As the ostrich unexpectly enters the weightless environment of the ");
        if (g.HERE == ELEVATOR) {
          tell("elevator");
        } else {
          tell("village");
        }
        tell(", it shoots into the air, squawking loudly. It spins head over claw for a moment, thrashing its wings ineffectually, before finally achieving a modicum of stability.");
      }
    }
    move(OSTRICH, g.HERE);
    crlf();
  }
  return true;
}

