async function ROB(who, where = false) {
  let n_ = 0, x = 0;
  x = first(who);
  for (;;) {
    if (x == 0) {
      return true;
    }
    n_ = next(x);
    if (!(hasFlag(x, WORNBIT))) {
      if (where) {
        move(x, where);
      } else {
        remove(x);
      }
    }
    x = n_;
  }
}

