async function FORM_SLOT_F() {
  if (isVerb(V.PUT) && (g.PRSI == PSEUDO_OBJECT)) {
    if (g.PRSO == CRUMPLED_FORM) {
      tell("The form's crumpledness prevents it from sliding into the slot.\n");
      return true;
    } else if ((g.PRSO == CLASS_THREE_SPACECRAFT_ACTIVATION_FORM) && (g.HERE == SPACETRUCK)) {
      if ((g.HERE == SPACETRUCK) && (await BOTH_SEATS_NOT_OCCUPIED())) {
        tell("The form is spit back out. ");
        return (await RECORDING("Safety precautions forbid the activation of the vehicle unless both the pilot and copilot seats are occupied"));
      } else {
        remove(g.PRSO);
        setFlag(g.PRSO, NDESCBIT);
        tell(S(g.FORM_ACCEPTED));
        return (await RECORDING("Spacecraft activated. Type in the course heading"));
      }
    } else if ((g.PRSO == ROBOT_USE_AUTHORIZATION_FORM) && (g.HERE == ROBOT_POOL)) {
      remove(g.PRSO);
      setFlag(g.PRSO, NDESCBIT);
      tell(S(g.FORM_ACCEPTED));
      return (await RECORDING("Authorization approved. Type the bin number of the desired robot"));
    } else if ((g.PRSO == ASSIGNMENT_COMPLETION_FORM) && (g.HERE == DECK_TWELVE)) {
      tell(S(g.FORM_REJECTED));
      return (await RECORDING("This form has not been validated by a commanding officer"));
    } else if ((g.PRSO == VILLAGE_FORM) && (g.HERE == SOUTH_CONNECTION || g.HERE == EAST_CONNECTION)) {
      if (!g.VILLAGE_FORM_VALIDATED) {
        tell(S(g.FORM_REJECTED));
        return (await RECORDING("This form has not been validated by a commanding officer"));
      } else {
        g.SCORE = g.SCORE + 6;
        g.ROBOT_EVILNESS = g.ROBOT_EVILNESS + 1;
        setFlag(IRIS_HATCH, OPENBIT);
        remove(g.PRSO);
        setFlag(g.PRSO, NDESCBIT);
        tell("The hatch begins irising open, then sparks and smokes and grinds to a halt. However, it's about half dilated, wide enough to pass through. Beyond, you can see a small, dingy connecting tube, rather than the clean and brightly-lit Sub-Module connector you might have expected.\n");
        return true;
      }
    } else if (g.PRSO == ROBOT_USE_AUTHORIZATION_FORM || g.PRSO == CLASS_THREE_SPACECRAFT_ACTIVATION_FORM || g.PRSO == ASSIGNMENT_COMPLETION_FORM || g.PRSO == VILLAGE_FORM) {
      tell(S(g.FORM_REJECTED));
      return (await RECORDING("Improper form for this location"));
    } else if (getProp(P.SIZE, g.PRSO) < 3) {
      tell("The slot swallows");
      await TPRINT_PRSO();
      tell(" and then spits it back.\n");
      return true;
    } else {
      return (await DOESNT_FIT("slot"));
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell(S(g.ONLY_BLACKNESS));
    return true;
  } else {
    return false;
  }
}

