async function REMOVE_CAREFULLY(obj) {
  let also = false;
  if (g.TIMER_CONNECTED && (obj == TIMER || obj == DETONATOR)) {
    g.TIMER_CONNECTED = false;
    also = true;
    if (await VISIBLE$(TIMER)) {
      tell(" (The timer is", S(g.NO_LONGER_ATTACHED));
    }
  } else if (g.EXPLOSIVE_CONNECTED && (obj == EXPLOSIVE || obj == DETONATOR)) {
    g.EXPLOSIVE_CONNECTED = false;
    if (await VISIBLE$(EXPLOSIVE)) {
      tell(" (The explosive is");
      if (also) {
        tell(" also");
      }
      tell(S(g.NO_LONGER_ATTACHED));
    }
  }
  if ((loc(EXPLOSIVE) == THERMOS) && !(hasFlag(THERMOS, OPENBIT))) {
    g.THERMOS_FILLED_WITH_GAS = true;
  }
  setFlag(obj, TOUCHBIT);
  clearFlag(obj, TRYTAKEBIT);
  return remove(obj);
}

