async function STAR_F() {
  if ((await TOUCHING$(STAR)) && hasFlag(STAR, TRYTAKEBIT) && !g.HANGING_IN_AIR) {
    tell("The star is above you, beyond your reach.\n");
    return true;
  } else if (isVerb(V.TAKE) && hasFlag(STAR, TRYTAKEBIT) && g.HANGING_IN_AIR) {
    clearFlag(STAR, TRYTAKEBIT);
    clearFlag(STAR, NDESCBIT);
    setFlag(STAR, TOUCHBIT);
    move(STAR, PROTAGONIST);
    g.ROBOT_EVILNESS = g.ROBOT_EVILNESS + 1;
    g.SCORE = g.SCORE + getProp(DIODE_M, P.VALUE);
    putProp(DIODE_M, P.VALUE, 0);
    tell("Taken.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    if (loc(DIODE_M) == STAR) {
      tell("It's blinking with a gentle, rhythmic light. ");
    }
    if (hasFlag(STAR, TRYTAKEBIT) && !g.HANGING_IN_AIR) {
      await PERFORM(V.TOUCH, STAR);
      return true;
    } else {
      tell("The back of the star ");
      if (hasFlag(STAR, OPENBIT)) {
        tell("is open");
      } else {
        tell("looks openable");
      }
      tell(S(g.PERIOD_CR));
      return true;
    }
  } else if (isVerb(V.PUT) && (g.PRSO == DIODE_J)) {
    remove(DIODE_J);
    tell("Once the diode is in place, the star begins blinking rapidly and erratically. Suddenly the diode bursts and the star goes dead.\n");
    return true;
  } else {
    return false;
  }
}

