async function PULPIT_F() {
  if (isVerb(V.CLIMB_ON, V.CLIMB_UP, V.STAND_ON, V.ENTER)) {
    if (g.HANGING_IN_AIR) {
      return await CANT_REACH(PULPIT);
    } else {
      tell("The pulpit sways, and you fall off.");
      if (!(hasFlag(PULPIT, TOUCHBIT))) {
        tell(" However, it wasn't a wasted effort: ");
        await PERFORM(V.EXAMINE, PULPIT);
        return true;
      } else {
        return crlf();
      }
    }
  } else if (isVerb(V.EXAMINE) && !(hasFlag(PULPIT, TOUCHBIT))) {
    setFlag(PULPIT, TOUCHBIT);
    tell("You discover that the pulpit seems openable!\n");
    return true;
  } else if (isVerb(V.SHOOT)) {
    remove(PULPIT);
    remove(SWITCH);
    tell("In a rain of hellfire and brimstone, the pulpit is banished.\n");
    return true;
  } else {
    return false;
  }
}

async function SWITCH_F() {
  if (isVerb(V.ON, V.OFF, V.THROW, V.PUSH, V.MOVE, V.SET)) {
    if (g.HANGING_IN_AIR) {
      await CANT_REACH(SWITCH);
      return true;
    }
    tell("The ", D(ETERNAL_FLAME), " ");
    if (hasFlag(ETERNAL_FLAME, ONBIT)) {
      clearFlag(ETERNAL_FLAME, ACTIVEBIT);
      clearFlag(ETERNAL_FLAME, ONBIT);
      tell("goes out!\n");
      return true;
    } else {
      setFlag(ETERNAL_FLAME, ACTIVEBIT);
      setFlag(ETERNAL_FLAME, ONBIT);
      tell("flickers back on.");
      if (loc(BALLOON) == g.HERE) {
        move(BALLOON, LEVEL_THREE);
        move(LEASH, LEVEL_THREE);
        tell(" The ", D(BALLOON), " shoots out of the Chapel.");
      }
      return crlf();
    }
  } else {
    return false;
  }
}

async function THEATRE_SEAT_F() {
  if (isVerb(V.ENTER, V.CLIMB_ON)) {
    g.PRSO = ROOMS;
    return await V_SIT();
  } else {
    return false;
  }
}

async function PROJECTION_BOOTH_F() {
  if (isVerb(V.OPEN, V.ENTER, V.WALK_TO, V.SEARCH)) {
    tell("The projection booth is closed and locked.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell(S(g.ONLY_BLACKNESS));
    return true;
  } else {
    return false;
  }
}

async function MESS_HALL_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This open dining area seats around 30 people. ", D(FPU), "s curve along the exterior wall. There's a doorway to the southeast, and doors lead north, south, and northeast. To the east are the elevator");
    if (!(g.ELEVATOR_LEVEL == 2)) {
      tell(" shaft");
    }
    tell(", the elevator button, and the up-down ladder.");
    return true;
  } else {
    return false;
  }
}

async function FPU_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The units curve around the outside wall of the Mess Hall. The interface is delightfully simple: a user simply turns on the unit and immediately receives a tasty and nutritionally-balanced meal.\n");
    return true;
  } else if (isVerb(V.ON)) {
    tell("A taped voice, in a cheery contralto, says, \"Good ");
    if (g.INTERNAL_MOVES < 3000) {
      tell("morning");
    } else if (g.INTERNAL_MOVES > 5000) {
      tell("evening");
    } else {
      tell("afternoon");
    }
    tell("! Today's menu features ");
    if (g.INTERNAL_MOVES < 3000) {
      tell("sausage, frobbled eggs, and teakberry juice");
    } else if (g.INTERNAL_MOVES > 5000) {
      tell("chicken pot pie, braised volpoid livers, and mashed Rigellian yams");
    } else {
      tell("a bacon, lettuce, and frombucko sandwich");
    }
    tell(". Eat hearty! Dispensing will now begin.\" A seamless hatch in the FDU opens, and a stream of acid shoots out. You leap aside as the acid etches the floor, leaving behind some acrid fumes.\n");
    return true;
  } else {
    return false;
  }
}

async function COFFEE_F(oarg = false) {
  if (oarg) {
    if (hasFlag(COFFEE, TOUCHBIT)) {
      return false;
    } else if (oarg == M_OBJDESC$) {
      return true;
    }
    tell("   A cup of thick brown coffee sits on one of the tables");
    if (g.DAY == 1) {
      tell(". It's still steaming, though there's no one in sight");
    }
    tell(".");
    return true;
  } else if (isVerb(V.POUR, V.EMPTY, V.THROW) && (g.PRSO == COFFEE)) {
    (await MESS("coffee"));
    return await ANTI_LITTER(COFFEE);
  } else if (isVerb(V.TASTE, V.EXAMINE, V.TOUCH, V.REACH_IN, V.LOOK_INSIDE) && (g.DAY == 1)) {
    tell("The coffee is still hot.\n");
    return true;
  } else if (isVerb(V.TASTE)) {
    tell("It tastes unusually bitter.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("The coffee has a vague chemical odor.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.REACH_IN, V.TOUCH)) {
    tell("The cup is filled with cold coffee.\n");
    return true;
  } else if (isVerb(V.EAT_FROM)) {
    await PERFORM(V.EAT, COFFEE);
    return true;
  } else if (isVerb(V.EAT)) {
    if (g.HUNGER_LEVEL == 0) {
      tell(S(g.NOT_HUNGRY));
      return true;
    } else {
      return (await JIGS_UP("Aaarghhh! The coffee is poisoned! It's eating away at your insides!!"));
    }
  } else {
    return false;
  }
}

async function DETONATOR_F() {
  if (isVerb(V.EXAMINE)) {
    tell("It's a state-of-the-art detonator, fairly cubical with two connection points. ");
    if (g.TIMER_CONNECTED) {
      tell("A timer is attached at one of those points");
      if (g.EXPLOSIVE_CONNECTED) {
        tell(", and an explosive is attached at the other");
      }
      tell(". ");
    } else if (g.EXPLOSIVE_CONNECTED) {
      tell("An explosive is attached at one of those points. ");
    }
    if (hasFlag(DETONATOR, OPENBIT)) {
      tell("The detonator is open");
      if (first(DETONATOR)) {
        tell(" and contains");
        await ARPRINT(first(DETONATOR));
        return true;
      } else {
        tell(S(g.PERIOD_CR));
        return true;
      }
    } else {
      tell("There is a faint crack running around the outside of the detonator, indicating that perhaps it can be opened.\n");
      return true;
    }
  } else if (isVerb(V.CONNECT)) {
    if (TIMER == g.PRSO || TIMER == g.PRSI) {
      if (g.TIMER_CONNECTED) {
        tell(S(g.SENILITY_STRIKES));
        return true;
      } else {
        g.TIMER_CONNECTED = true;
        tell("Done.\n");
        return true;
      }
    } else if (EXPLOSIVE == g.PRSO || EXPLOSIVE == g.PRSI) {
      if (g.EXPLOSIVE_CONNECTED) {
        tell(S(g.SENILITY_STRIKES));
        return true;
      } else {
        g.EXPLOSIVE_CONNECTED = true;
        tell("Done (Footnote 13).\n");
        return true;
      }
    } else {
      tell(S(g.YOU_CANT), "connect the detonator to that!\n");
      return true;
    }
  } else if (isVerb(V.DISCONNECT)) {
    if (!g.PRSI) {
      if (g.EXPLOSIVE_CONNECTED || g.TIMER_CONNECTED) {
        tell(S(g.DETACH));
        if (g.TIMER_CONNECTED) {
          tell("the timer");
          if (g.EXPLOSIVE_CONNECTED) {
            tell(" and the explosive");
          }
        } else {
          tell("the explosive");
        }
        g.EXPLOSIVE_CONNECTED = false;
        g.TIMER_CONNECTED = false;
        tell(S(g.PERIOD_CR));
        return true;
      } else {
        return false;
      }
    } else if ((EXPLOSIVE == g.PRSO || EXPLOSIVE == g.PRSI) && g.EXPLOSIVE_CONNECTED) {
      g.EXPLOSIVE_CONNECTED = false;
      tell(S(g.DETACH), "the explosive.\n");
      return true;
    } else if ((TIMER == g.PRSO || TIMER == g.PRSI) && g.TIMER_CONNECTED) {
      g.TIMER_CONNECTED = false;
      tell(S(g.DETACH), "the timer.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.PUT) && (g.PRSI == DETONATOR) && hasFlag(DETONATOR, OPENBIT)) {
    if (!(g.PRSO == DIODE_J || g.PRSO == DIODE_M || g.PRSO == BLACKENED_DIODE)) {
      return (await DOESNT_FIT("detonator"));
    } else if (first(DETONATOR)) {
      tell("There's a ", D(first(DETONATOR)), " in the way.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function BLACKENED_DIODE_F() {
  if (isVerb(V.CLEAN)) {
    if (g.DIODE_CLEANED) {
      tell("You've de-charred the diode to the max.\n");
      return true;
    } else {
      g.DIODE_CLEANED = true;
      tell("You scrape off enough black that y", S(g.MAKE_OUT_AN_M));
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (g.DIODE_CLEANED) {
      tell("Y", S(g.MAKE_OUT_AN_M));
      return true;
    } else {
      tell("The diode is so charred you can't even tell what series it is.\n");
      return true;
    }
  } else if (isVerb(V.COMPARE) && ((DIODE_J == g.PRSO || DIODE_J == g.PRSI) || (DIODE_M == g.PRSO || DIODE_M == g.PRSI))) {
    tell("They're identical in size and shape, but");
    await TPRINT(BLACKENED_DIODE);
    tell(" is covered with char.\n");
    return true;
  } else {
    return false;
  }
}

async function MAGAZINE_F() {
  if (isVerb(V.TAKE)) {
    return (await RECORDING("Magazines are not to be removed from the library"));
  } else if (isVerb(V.READ, V.OPEN, V.EXAMINE, V.LOOK_INSIDE)) {
    tell("You glance at the magazines. The most familiar ones are \"Popular Patrolling,\" \"The Galactic Enquirer,\" and \"True Tales of Adventure.\" However, they're all issues which you've already read back on the Duffy, so they're not too interesting.\n");
    return true;
  } else {
    return false;
  }
}

async function NANOFILM_READER_F() {
  let spool = 0;
  spool = first(NANOFILM_READER);
  if (isVerb(V.CLOSE)) {
    tell(S(g.HUH));
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The ", D(NANOFILM_READER), " must be a voice-output model, since it has no screen. The reader is o");
    if (hasFlag(NANOFILM_READER, ACTIVEBIT)) {
      tell("n");
    } else {
      tell("ff");
    }
    tell(", and there is ");
    if (spool) {
      tell("a ", D(spool));
    } else {
      tell("no spool");
    }
    tell(" in the reader.\n");
    return true;
  } else if (isVerb(V.PUT)) {
    if (!(g.PRSO == MAUVE_SPOOL || g.PRSO == PUCE_SPOOL || g.PRSO == LILAC_SPOOL)) {
      tell("It doesn't fit.\n");
      return true;
    } else if (spool) {
      tell("There's already a spool in the reader.\n");
      return true;
    } else if (hasFlag(NANOFILM_READER, ACTIVEBIT)) {
      move(g.PRSO, NANOFILM_READER);
      clearFlag(NANOFILM_READER, ACTIVEBIT);
      await PERFORM(V.ON, NANOFILM_READER);
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ON) && !(hasFlag(NANOFILM_READER, ACTIVEBIT)) && spool) {
    setFlag(NANOFILM_READER, ACTIVEBIT);
    tell("The reader, in a surprisingly human voice, says, \"");
    if (spool == MAUVE_SPOOL) {
      tell("Gamma-Delta-Gamma class Deep-Space Stations are equipped with a full range of collating machinery. The workhorse of the...\" There is a burst of static from the reader. \"...common malfunction of this large collater. First check the lower fromitz...\" More static. \"...and replace with");
    } else if (spool == LILAC_SPOOL) {
      tell("Replacement of depleted fuel cells on a Forms Transport ", D(SPACETRUCK), " is a fast and simple proc...\" Static. \"...with the quarnum wrench against the...\" More serious static. \"...at which point the fuel cell opening will appear");
    } else {
      tell("Maintenance of the chapel equipment is simple, and should take little time away from your Chaplain duties. Fuel must be added periodically to the flame's fuel reservoir, located...\" A loud burst of static drowns out the recording. \"...ontact the station's Requisitions Officer if replacements are unavailable from the...\" More static. \"...iode in the Chapel's star has an expected life of");
    }
    tell("...\" A long burst of static. Suddenly the voice changes in timbre and begins laughing and saying, \"You will die, human! All humans will die! You will die, human!\"\n");
    return true;
  } else {
    return false;
  }
}

async function DOME_OBJECT_F() {
  if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell(S(g.DOME_DESC), "\n");
    return true;
  } else if (isVerb(V.WALK_AROUND)) {
    return await DO_WALK(P.NORTH);
  } else {
    return false;
  }
}

async function DOME_F(rarg) {
  if (rarg == M_LOOK) {
    tell("This is inarguably the most bucolic spot aboard the station. Pebbled paths wind among beautiful and exotic shrubbery, culled from millenia of galactic exploration. ", S(g.DOME_DESC), " East of where you are standing are an elevator");
    if (!(g.ELEVATOR_LEVEL == 1)) {
      tell(" shaft");
    }
    tell(", a button, and the top of a ladder. Next to the ladder ");
    if (g.GRATING_LOOSE) {
      tell("is");
    } else {
      tell("are");
    }
    tell(" an ", D(GRATING));
    if (hasFlag(GRATING, TOUCHBIT)) {
      tell(", which has been bent back from the air shaft to form an opening.");
      return true;
    } else if (g.GRATING_LOOSE) {
      tell(", which looks a bit loose.");
      return true;
    } else {
      tell(" and a thick metal ", D(HOUSING), " with a sign stencilled on it.");
      return true;
    }
  } else {
    return false;
  }
}

async function SHRUBBERY_F() {
  if (isVerb(V.EXAMINE)) {
    tell("There are too many varieties to describe them all: junipers, rose bushes, dogwoods, gliffgubbers, Rhomboidal Pellet Trees...\n");
    return true;
  } else if (isVerb(V.SHOOT)) {
    tell("One of the many shrubs is now history, you plant-hater.\n");
    return true;
  } else if (isVerb(V.EAT)) {
    tell("None of the plants are edible.\n");
    return true;
  } else if (isVerb(V.WALK_AROUND)) {
    return await DO_WALK(P.NORTH);
  } else if (isVerb(V.SEARCH, V.LOOK_INSIDE)) {
    tell("You find nothing besides a few repulsive insects.\n");
    return true;
  } else if (isVerb(V.ENTER)) {
    tell("A few hidden thorns cause a quick change of plan.\n");
    return true;
  } else {
    return false;
  }
}

async function HOUSING_F() {
  if (isVerb(V.UNLOCK) && (g.PRSI == KEY)) {
    clearFlag(HOUSING, LOCKEDBIT);
    tell("You unlock the bin.\n");
    return true;
  } else if (isVerb(V.PUT) && (g.PRSO == KEY) && (await NOUN_USED(W.LOCK, HOUSING))) {
    await PERFORM(V.UNLOCK, HOUSING, KEY);
    return true;
  } else if (isVerb(V.OPEN) && !(hasFlag(HOUSING, LOCKEDBIT))) {
    g.GRATING_LOOSE = true;
    await QUEUE(I_ANNOUNCEMENT.id, 140);
    await DEQUEUE(I_SLEEP_WARNINGS.id);
    await DEQUEUE(I_HUNGER_WARNINGS.id);
    await ROB(PROTAGONIST, g.HERE);
    remove(HOUSING);
    await MOVE_FLOYD_TO_FACTORY();
    tell("You open the bin, revealing fertilizer, gardening tools, and a supply of fuel cells. Suddenly, the cells explode! The heat and shock toss you halfway across the dome! Your solitary thought before succumbing to unconsciousness is how grateful you are that you landed in such a soft shrub.\n\n...an undetermined amount of time later, you come to, shake away the cobwebs, and look around", S(g.ELLIPSIS));
    await V_LOOK();
    return g.C_ELAPSED = 63;
  } else if (isVerb(V.DRILL)) {
    return await MAKE_HOLE_WITH_DRILL(HOUSING);
  } else if (isVerb(V.EXAMINE)) {
    tell("The bin is closed, and there's a sign on it");
    if (loc(DRILLED_HOLE) == g.HERE) {
      tell(". A hole has been drilled in it");
      await DESCRIBE_BIT_SIZE(g.HOLE_SIZE);
    }
    tell(". A lock has been newly welded to the bin. ");
    await PERFORM(V.TOUCH, HOUSING);
    return true;
  } else if (isVerb(V.PICK)) {
    await PERFORM(V.PICK, STRONG_BOX);
    return true;
  } else if (isVerb(V.TOUCH)) {
    tell("The bin is warm to the touch.\n");
    return true;
  } else {
    return false;
  }
}

async function GRATING_F() {
  if ((g.HERE == COMPUTER_CONTROL) && (await TOUCHING$(GRATING))) {
    return await CANT_REACH(GRATING);
  } else if (isVerb(V.PUT)) {
    return await WASTES();
  } else if (g.HERE == BOTTOM_OF_AIR_SHAFT) {
    if (isVerb(V.OPEN, V.KICK, V.STAND_ON)) {
      await QUEUE(I_ANNOUNCEMENT.id, 1);
      tell("The grating opens, spilling you into the room below", S(g.ELLIPSIS));
      await QUEUE(I_EXERCISE_MACHINE.id, -1);
      await ROB(BOTTOM_OF_AIR_SHAFT, COMPUTER_CONTROL);
      await ROB(PEDESTAL);
      move(PEDESTAL, FACTORY);
      move(PYRAMID, PEDESTAL);
      return await GOTO(COMPUTER_CONTROL);
    } else if (isVerb(V.ENTER)) {
      return (await DO_FIRST("open the grating"));
    } else if (isVerb(V.LOOK_INSIDE)) {
      tell("There's a lighted area below the grating, but you can't see any details.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (hasFlag(GRATING, TOUCHBIT)) {
      tell("The grating has been bent back far enough for you to squeeze through.\n");
      return true;
    } else if (g.GRATING_LOOSE) {
      tell("The ", D(GRATING), " looks loose.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.ENTER)) {
    if (g.HERE == TOP_OF_AIR_SHAFT) {
      return await GOTO(DOME);
    } else if (g.HERE == COMPUTER_CONTROL) {
      await PERFORM(V.TOUCH, GRATING);
      return true;
    } else if (hasFlag(GRATING, TOUCHBIT)) {
      await DEQUEUE(I_WELDER.id);
      return await GOTO(TOP_OF_AIR_SHAFT);
    } else {
      tell("Impossible, unless you can pass through holes a centimeter across.\n");
      return true;
    }
  } else if (isVerb(V.PUSH, V.MOVE, V.TAKE, V.OPEN)) {
    if (!g.LIT) {
      tell(S(g.TOO_DARK), "\n");
      return true;
    } else if (hasFlag(GRATING, TOUCHBIT)) {
      tell(S(g.SENILITY_STRIKES));
      return true;
    } else if (g.GRATING_LOOSE) {
      setFlag(GRATING, TOUCHBIT);
      tell("With effort, you bend the grating and form an opening large enough to enter.\n");
      return true;
    } else {
      tell("The grating is securely affixed.\n");
      return true;
    }
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell(S(g.ONLY_BLACKNESS));
    return true;
  } else {
    return false;
  }
}

async function LEVEL_SIX_F(rarg) {
  if (rarg == M_LOOK) {
    tell("The elevator button is east of you, next to the elevator");
    if (!(g.ELEVATOR_LEVEL == 6)) {
      tell(" shaft");
    }
    tell(". This main corridor continues around the shaft to the southeast. Huge doors lie just northwest and southwest of here; smaller doors lead north and south", S(g.LADDER_LEADS));
    return true;
  } else {
    return false;
  }
}

