async function ELEVATOR_ENTER_F() {
  tell("The ", D(ELEVATOR_SHAFT), " is s");
  if (g.DAY > 2) {
    tell("upposed to be a weightless environment, outside of the station's artificial gravity field. But the gravity in the shaft is one standard Gee!");
  } else {
    tell("hielded from the station's artificial gravity field, and your stomach gives a little flip as you enter the weightless environment.");
  }
  crlf();
  crlf();
  if (eq(getProp(g.HERE, P.LEVEL), g.ELEVATOR_LEVEL)) {
    return ELEVATOR;
  } else {
    tell("Elevator Shaft\n   ");
    if (g.DAY > 2) {
      if (eq(g.ELEVATOR_LEVEL - 1, getProp(g.HERE, P.LEVEL))) {
        tell("You drop a short distance to the top of the elevator, which is fortunately sitting one level below. You are able to easily climb back out of the shaft.");
      } else {
        (await JIGS_UP("Oh, no! The elevator isn't at this floor! It's a long plunge..."));
      }
    } else {
      tell("You float helplessly in the shaft. After a few millichrons of useless flailing, you decide that summoning the elevator might be a good idea, and you pull yourself out of the shaft, back to the one-gee environment.");
    }
    crlf();
    crlf();
    await DESCRIBE_ROOM();
    return false;
  }
}

async function CALL_BUTTON_F() {
  let this_level = 0;
  if (isVerb(V.PUSH)) {
    if (g.GRATING_LOOSE || (g.HERE == COMPUTER_CONTROL)) {
      tell(S(g.NOTHING_HAPPENS));
      return true;
    }
    this_level = getProp(g.HERE, P.LEVEL);
    if (this_level == g.ELEVATOR_LEVEL) {
      tell("The elevator is already here!\n");
      return true;
    } else {
      g.C_ELAPSED = 5 * (this_level > g.ELEVATOR_LEVEL ? (this_level - g.ELEVATOR_LEVEL) : (g.ELEVATOR_LEVEL - this_level));
      g.ELEVATOR_LEVEL = this_level;
      tell("You feel a whoosh of warm air from the shaft. A few millichrons later, the elevator appears, stopping level with the deck.\n");
      return true;
    }
  } else {
    return false;
  }
}

