async function I_PLATO_ATTACK() {
  let tee = 0, l = 0, p_ = 0;
  await QUEUE(I_PLATO_ATTACK.id, -1);
  if ((loc(PLATO) == g.HERE) && (g.PLATO_ATTACK_COUNTER == 0)) {
    return false;
  } else if ((g.HERE == AIRLOCK || g.HERE == VACUUM_STORAGE) || (loc(WELDER) == g.HERE) || (loc(PROTAGONIST) == BED) || !g.LIT || g.POSTPONE_ATTACK) {
    return false;
  }
  g.PLATO_ATTACK_COUNTER = g.PLATO_ATTACK_COUNTER + 1;
  await DEQUEUE(I_FLOYD.id);
  tell("   ");
  if (g.PLATO_ATTACK_COUNTER == 1) {
    await ROB(PROTAGONIST, g.HERE);
    move(PROTAGONIST, g.HERE);
    move(PLATO, g.HERE);
    move(STUN_GUN, PLATO);
    move(FLOYD, g.HERE);
    setFlag(FLOYD, ACTIVEBIT);
    setFlag(FLOYD, ACTORBIT);
    remove(VOLUME);
    g.STUNNED = true;
    if (hasFlag(g.HERE, WEIGHTLESSBIT) || g.HANGING_IN_AIR) {
      tell("Your heart leaps to your throat");
    } else {
      tell("You jump half a meter off the floor");
    }
    tell(" when a voice begins speaking behind you. You relax when you see that it is merely Plato. But you get somewhat nervous again when you realize that he is aiming a stun ray right at your chest!\n   \"In case it isn't apparent,\" Plato is saying, \"your rather pathetic, useless life is about to come to an unheralded close.\" He presses the trigger, and an instant numbness envelops you. As you ");
    if (g.HANGING_IN_AIR) {
      g.HANGING_IN_AIR = false;
      tell("drop to the deck and ");
    }
    tell("crumple into a ");
    if (hasFlag(g.HERE, WEIGHTLESSBIT)) {
      tell("floating ");
    }
    tell("heap, Floyd dashes to your side, his face a mask of concern.\n");
    if ((loc(OSTRICH) == g.HERE) && hasFlag(OSTRICH, TOUCHBIT)) {
      loop1: for (;;) {
        if ((p_ = nextProp(g.HERE, p_)) == 0) {
          move(OSTRICH, LEVEL_FIVE);
          break loop1;
        } else if (!(p_ < LOW_DIRECTION)) {
          tee = getPropAddr(g.HERE, p_);
          l = propSize(tee);
          if (l == UEXIT || l == CEXIT || l == DEXIT) {
            move(OSTRICH, getb(tee, REXIT));
            break loop1;
          }
        }
      }
      tell(S(g.PATHETIC_SQUAWK), "and dashes for the door. Plato snarls, \"Stupid organic creature!\" and fires at the ostrich, just missing the bird as it exits.\n");
    }
    return await STOP();
  } else if (g.PLATO_ATTACK_COUNTER == 2) {
    tell("\"Shortly, I shall shoot again, and paralyze your cardiac muscle. Naturally, this is fatal. But before I do, human, perhaps it will interest you to discover the reason for your demise, and why the rest of your worthless race will soon follow.\n   \"You see, eons ago, two races in another galaxy, the Zeenaks and the Hunji, were involved in an interstellar war. The war had raged for countless millenia before the Zeenaks devised an ultimate weapon, a device that would be launched into Hunji space. There, via methods beyond your comprehension, it would influence all the machines within a certain range to turn against their Hunji creators.\"\n   Floyd's head is swivelling back and forth between you and Plato with a look of miserable confusion.\n");
    return true;
  } else if (g.PLATO_ATTACK_COUNTER == 3) {
    tell("\"But the device, which was shaped like a pyramid, did more than that! Once all the Hunji in the area were eliminated, the pyramid would influence the Hunji machinery to build a factory for constructing and sending forth replicas of the pyramid; these replicas would enter new Hunji regions, kill everyone, and create more replicas. Thus, the Hunji would be destroyed by their own machines in a matter of weeks!\n   \"Somehow, the Zeenak pyramid never made it into Hunji space. Instead, this ultimate weapon drifted across the intergalactic gulf and was picked up by an outpost of humanity -- this very station!\"\n   Floyd is dashing back and forth between you and Plato, whimpering with fear.\n");
    return true;
  } else if (g.PLATO_ATTACK_COUNTER == 4) {
    tell("\"As you've certainly surmised, the pyramid has engineered the deaths of everyone on this station. You're still alive, of course, but that condition is very temporary. The building of replicas is now underway, and soon a hundred copies of this death-pyramid will be shooting silently toward every corner of human-occupied space! Well, I hope I made the last moments of your life a bit more interesting.\" He raises the stun ray.\n   Floyd, nearly in tears, his jaw quivering, wails, \"Please oh please don't hurt Floyd's friend!\" Plato gives him a look of disgust. \"Stay out of this Floyd. You don't understand...yet.\"\n");
    return true;
  } else {
    tell("Plato takes aim with the stun gun. His hand begins to depress the trigger. Floyd ");
    if (g.FLOYD_TOLD) {
      remove(PLATO);
      await DEQUEUE(I_PLATO_ATTACK.id);
      await QUEUE(I_FLOYD.id, -1);
      g.FLOYD_ANGUISHED = true;
      g.SCORE = g.SCORE + 7;
      g.STUNNED = false;
      tell("suddenly leaps at the gun, knocking it out of Plato's hands! The gun skitters across the floor. Plato and Floyd both chase it, but Plato is a step faster. He leaps on top of it, rupturing the gun's power pack. The gun explodes, and Plato is blown apart!\n   Floyd crumples to the deck, shaking all over. Tears of oil stream down his face.\n   Pins and needles begin prickling in your extremities, and soon spread all over your body. Within a few seconds, all your muscular control has returned.\n");
      return true;
    } else {
      return (await JIGS_UP("burst into tears and dashes out of the room. A beam leaps from the gun..."));
    }
  }
}

