async function DICE_F() {
  let num = 0;
  if (isVerb(V.ROLL, V.THROW)) {
    if (!(await ULTIMATELY_IN$(DICE))) {
      tell(S(g.YNH));
      await TRPRINT(DICE);
      return true;
    } else if (hasFlag(g.HERE, WEIGHTLESSBIT)) {
      if (prob(50)) {
        num = 7;
      } else {
        num = 11;
      }
    } else {
      num = random(6) + random(6);
    }
    move(DICE, g.HERE);
    tell("You roll a");
    if (num == 8 || num == 11) {
      tell("n");
    }
    tell(" ", N(num));
    if (hasFlag(g.HERE, WEIGHTLESSBIT) && !g.DICE_FOOTNOTE) {
      g.DICE_FOOTNOTE = true;
      tell(" (Footnote 1)");
    }
    tell(S(g.PERIOD_CR));
    return true;
  } else if (isVerb(V.SHAKE)) {
    tell("Shaken.\n");
    return true;
  } else {
    return false;
  }
}

